import axios from "axios";

const API = axios.create({
  baseURL: "http://127.0.0.1:5000",
});

// 🔐 LOGIN
export const loginUser = (data) => API.post("/login", data);

// 📊 DASHBOARD
export const getDashboard = (token) =>
  API.get("/dashboard", {
    headers: { Authorization: token }
  });

// 📢 NOTICES
export const getNotices = () => API.get("/notices");

export const addNotice = (data, token) =>
  API.post("/add-notice", data, {
    headers: { Authorization: token }
  });

// ✅ FIX: DELETE NOTICE
export const deleteNotice = (id, token) =>
  API.delete(`/delete-notice/${id}`, {
    headers: { Authorization: token }
  });

// 📚 STUDY
export const getStudy = () => API.get("/study");

export const addStudy = (data, token) =>
  API.post("/add-study", data, {
    headers: { Authorization: token }
  });

// 📁 FIX: UPLOAD PDF
export const uploadPDF = (file, token) => {
  const formData = new FormData();
  formData.append("file", file);

  return API.post("/upload-pdf", formData, {
    headers: {
      Authorization: token,
      "Content-Type": "multipart/form-data"
    }
  });
};

// 💬 CHAT
export const sendMessage = (message) =>
  API.post("/chat", { message });
